use bevy::math::{DQuat,DVec3};
use bevy_als::extensions::control_rig_hierarchy::{RigTransform,rig_normalize};
use serde_json::{Value,json};
mod prior{include!("../471/replay.rs");pub fn source_normalize(v:[f64;4])->[f64;4]{normalize(v)}}
type Q=[f64;4];
fn q(v:&Value)->Q{[v["x"].as_f64().unwrap(),v["y"].as_f64().unwrap(),v["z"].as_f64().unwrap(),v["w"].as_f64().unwrap()]}
fn vec(v:&Value)->DVec3{DVec3::new(v["x"].as_f64().unwrap(),v["y"].as_f64().unwrap(),v["z"].as_f64().unwrap())}
fn project(v:Q)->Q{[-v[0],-v[2],-v[1],v[3]]}
fn vector_project(v:DVec3)->DVec3{DVec3::new(v.x,v.z,v.y)}
fn transform(v:&Value)->RigTransform{RigTransform{rotation:DQuat::from_array(project(q(&v["rotation"]))),translation:vector_project(vec(&v["translation"]))*0.01,scale:vector_project(vec(&v["scale"]))}}
fn source(a:&Value,b:&Value,mask:u8)->Value{let a_t=vec(&a["translation"]);let b_t=vec(&b["translation"]);let a_q=q(&a["rotation"]);let b_q=q(&b["rotation"]);assert_eq!(vec(&a["scale"]),DVec3::ONE);assert_eq!(vec(&b["scale"]),DVec3::ONE);let inverse=[-b_q[0],-b_q[1],-b_q[2],b_q[3]];let product=if mask&1!=0{(DQuat::from_array(inverse)*DQuat::from_array(a_q)).to_array()}else{project((DQuat::from_array(project(inverse))*DQuat::from_array(project(a_q))).to_array())};let rotation=if mask&2!=0{prior::source_normalize(product)}else{project(rig_normalize(DQuat::from_array(project(product))).to_array())};let translation=if mask&4!=0{let q=DVec3::from_slice(&inverse[..3]);let v=a_t-b_t;let t=q.cross(v)*2.0;(v+t*inverse[3])+q.cross(t)}else{vector_project((DQuat::from_array(project(inverse))*vector_project((a_t-b_t)*0.01)))*100.0};json!({"rotation":rotation,"translation":translation,"scale":[1.0,1.0,1.0],"product":product})}
fn model_transform(v:&Value)->RigTransform{let q=std::array::from_fn(|i|v["rotation"][i].as_f64().unwrap());let t=DVec3::from_array(std::array::from_fn(|i|v["translation"][i].as_f64().unwrap()));RigTransform{rotation:DQuat::from_array(project(q)),translation:vector_project(t)*0.01,scale:DVec3::ONE}}
fn exact_native(v:&Value,native:&Value)->bool{std::array::from_fn::<_,4,_>(|i|v["rotation"][i].as_f64().unwrap())==q(&native["rotation"])&&DVec3::from_array(std::array::from_fn(|i|v["translation"][i].as_f64().unwrap()))==vec(&native["translation"])}
fn main(){let root=std::path::Path::new("docs/audit/bf144/474");let label=std::env::args().nth(1).unwrap();let input:Value=serde_json::from_slice(&std::fs::read(root.join("inputs.json")).unwrap()).unwrap();let mut outputs=Vec::new();let mut native_exact=0;let mut current_exact=0;let mut first=None;for row in input["source"].as_array().unwrap(){for mask in 0..8{let out=source(&row["global_transform"],&row["parent_global"],mask);let exact=exact_native(&out,&row["native_local"]);if mask==7{native_exact+=exact as usize;if !exact&&first.is_none(){first=Some(json!({"input":row,"stages":out}));}}if mask==0{let public=transform(&row["global_transform"]).relative(transform(&row["parent_global"]));assert_eq!(public,model_transform(&out),"Qualified current relative mathematical model");}outputs.push(json!({"dataset":row["dataset"],"case":row["case"],"query":row["query"],"foot":row["foot"],"mask":mask,"stages":out,"native":row["native_local"],"exact":exact}));}}
 let mut actual=Vec::new();for row in input["actual"].as_array().unwrap(){let a:RigTransform=serde_json::from_value(row["global_transform"].clone()).unwrap();let b:RigTransform=serde_json::from_value(row["parent_global"].clone()).unwrap();let expected:RigTransform=serde_json::from_value(row["expected_local"].clone()).unwrap();let out=a.relative(b);current_exact+=(out==expected)as usize;actual.push(json!({"mode":row["mode"],"query":row["query"],"foot":row["foot"],"result":out,"expected":expected,"exact":out==expected}));}std::fs::write(root.join(format!("replay-{label}.json")),serde_json::to_vec(&json!({"gate":"SOURCE_FOOT_GLOBAL_TO_LOCAL_CACHE_QUALIFICATION","source_exact":native_exact,"current_actual_exact":current_exact,"first":first,"outputs":outputs,"actual":actual})).unwrap()).unwrap();assert_eq!(native_exact,696,"Complete source foot global-to-local endpoint");assert_eq!(current_exact,1272,"Actual target local cache recomputation");println!("Qualified696 source and1272 actual foot local endpoints");}
